// ─── Fonte Fraunces para as imagens geradas no servidor (satori) ─────────────
// Usada tanto pelos slides do Instagram (/api/og) quanto pela imagem de
// compartilhamento do site (app/[lang]/opengraph-image.tsx). Mora aqui para as
// duas beberem do mesmo arquivo em vez de cada uma embutir a sua cópia.
const FONT_B64 = "";

export function loadFraunces(): ArrayBuffer {
  const bin = atob(FONT_B64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}
